"""Waypoint folder-note indexes, generated by exactly one writer.

The Obsidian Waypoint plugin rewrites a folder note's index whenever
something in the folder changes - on every machine where Obsidian runs, and
for changes the sync delivers too. With Obsidian open on two machines (or
one Obsidian plus a script writing the same notes in a different layout),
the same folder note gets modified in two places before they sync: a sync
conflict.

The fix is a single writer: disable the plugin in Obsidian and let the save
service (always running, on the machine every change syncs through)
regenerate the indexes. This module reproduces the plugin's output (2.1.0,
default settings: tabs, wikilinks, folder notes inside their folder, scan
stops at subfolders that have their own Waypoint, Landmarks don't stop it,
`_attachments` ignored), so the notes look exactly as the plugin's and it
can be switched back on at any time.

Pure functions over a vault path - no service settings imported at module
level - so the vault-maintenance skill can use the same generator.
"""
import os
import re
import threading
import time
import unicodedata
from pathlib import Path

# Every marker is assembled at runtime: the Waypoint plugin scans every vault
# file (this one included) for its trigger text and would rewrite this source.
_PCT = "%" * 2
WAYPOINT_FLAG = f"{_PCT} Waypoint {_PCT}"
LANDMARK_FLAG = f"{_PCT} Landmark {_PCT}"
KINDS = {
    "waypoint": (f"{_PCT} Begin Waypoint {_PCT}", f"{_PCT} End Waypoint {_PCT}", WAYPOINT_FLAG, "[!waypoint]"),
    "landmark": (f"{_PCT} Begin Landmark {_PCT}", f"{_PCT} End Landmark {_PCT}", LANDMARK_FLAG, "[!landmark]"),
}
BEGIN_WAYPOINT = KINDS["waypoint"][0]
IGNORE_PATTERNS = [re.compile("_attachments")]
# Top-level folders not scanned: Dumps/ holds hundreds of thousands of files
# (cloned repos) and no folder notes.
SKIP_TOP_LEVEL = {"Dumps"}


# ---------------------------------------------------------------------------
# rendering
# ---------------------------------------------------------------------------
def _char_class(ch: str) -> int:
    """ICU root collation groups: spaces < punctuation < symbols < digits < letters."""
    if ch.isspace():
        return 0
    category = unicodedata.category(ch)
    if category.startswith("P"):
        return 1
    if category.startswith("S"):
        return 2
    return 4


def collation_key(name: str):
    """Approximates JS `a.localeCompare(b, undefined, {numeric: true,
    sensitivity: "base"})`: case- and accent-insensitive, digit runs
    compared as numbers. The name itself breaks ties deterministically."""
    folded = "".join(c for c in unicodedata.normalize("NFKD", name) if not unicodedata.combining(c)).casefold()
    key = []
    for part in re.split(r"(\d+)", folded):
        if not part:
            continue
        if part.isdigit():
            key.append((3, int(part), ""))
        else:
            key.extend((_char_class(c), 0, c) for c in part)
    return key, name


class Renderer:
    """Renders folder indexes for one vault, caching folder-note contents
    for the duration of one refresh."""

    def __init__(self, vault: Path):
        self.vault = Path(vault)
        self._texts = {}

    def _rel(self, path: Path) -> str:
        return path.relative_to(self.vault).as_posix()

    def _ignored(self, path: Path) -> bool:
        rel = self._rel(path)
        return any(p.search(rel) for p in IGNORE_PATTERNS)

    def read(self, note: Path) -> str:
        if note not in self._texts:
            try:
                self._texts[note] = note.read_text(encoding="utf-8", errors="replace")
            except OSError:
                self._texts[note] = ""
        return self._texts[note]

    @staticmethod
    def _children(folder: Path):
        # Unlike the plugin, sync conflict copies (Syncthing's naming) are left out: listing
        # "x.sync-conflict-2026…" as a note is noise, not an index entry.
        try:
            return [c for c in folder.iterdir() if not c.name.startswith(".") and ".sync-conflict-" not in c.name]
        except OSError:
            return []

    def _rep(self, node: Path, indent: int, top: bool = False):
        prefix = "\t" * indent + "-"
        if self._ignored(node):
            return None
        if node.is_file():
            return f"{prefix} [[{node.stem}]]" if node.suffix == ".md" else None
        out = ""
        if not top:
            out = f"{prefix} **{node.name}**"
            note = node / f"{node.name}.md"
            if note.is_file():
                out = f"{prefix} **[[{note.stem}]]**"
                text = self.read(note)
                if BEGIN_WAYPOINT in text or WAYPOINT_FLAG in text:
                    return out  # the subfolder lists itself
        children = self._children(node)
        if not children:
            return f"{prefix} **{node.name}**"
        children.sort(key=lambda c: collation_key(c.name))
        children = [c for c in children if c.name != f"{node.name}.md" and not self._ignored(c)]
        if children:
            child_indent = indent if top else indent + 1
            reps = [r for r in (self._rep(c, child_indent) for c in children) if r]
            out += ("" if out == "" else "\n") + "\n".join(reps)
        return out

    def tree(self, folder: Path) -> str:
        return self._rep(folder, 0, top=True) or ""


def apply_block(text: str, tree: str, kind: str):
    """The note's text with its Waypoint/Landmark block regenerated (the
    plugin's updateWaypoint: replaces the flag line, or everything from the
    Begin to the End marker, and keeps the rest of the note). None when the
    note has no such block."""
    begin, end, flag, callout_tag = KINDS[kind]
    block = f"{begin}\n{tree}\n\n{end}"
    lines = text.split("\n")
    start = stop = -1
    callout = had_flag = False
    for i, line in enumerate(lines):
        stripped = line.strip()
        if start == -1 and (flag in stripped or begin in stripped):
            callout, had_flag, start = stripped.startswith(">"), flag in stripped, i
            continue
        if start != -1 and stripped.lstrip(">").strip() == end:
            stop = i
            break
    if start == -1:
        return None
    if callout:
        if had_flag:
            block = f"{callout_tag}\n{block}"
        block = "\n".join(f">{line}" for line in block.split("\n"))
    lines[start:(stop + 1 if stop != -1 else start + 1)] = [block]
    return "\n".join(lines)


def _folders(vault: Path):
    for dirpath, dirnames, _filenames in os.walk(vault):
        here = Path(dirpath)
        dirnames[:] = sorted(d for d in dirnames if not d.startswith(".")
                             and not (here == vault and d in SKIP_TOP_LEVEL))
        if here != vault:  # the plugin refuses a Waypoint in the vault root
            yield here


def plan(vault) -> list:
    """[(folder note, new text)] for every folder note whose index is stale."""
    vault = Path(vault)
    renderer = Renderer(vault)
    changes = []
    for folder in _folders(vault):
        note = folder / f"{folder.name}.md"
        if not note.is_file():
            continue
        text = renderer.read(note)
        new = text
        for kind, (begin, _end, flag, _tag) in KINDS.items():
            if begin in new or flag in new:
                updated = apply_block(new, renderer.tree(folder), kind)
                if updated is not None:
                    new = updated
        if new != text:
            changes.append((note, new))
    return changes


def refresh(vault, write: bool = True) -> list:
    """Regenerate every stale index. Returns the folder notes changed."""
    changes = plan(vault)
    if write:
        for note, text in changes:
            note.write_text(text, encoding="utf-8")
    return [note for note, _ in changes]


def structure_signature(vault) -> int:
    """Changes whenever an index could change: a file or folder added,
    removed or renamed, or a folder note edited (e.g. a flag added)."""
    vault = Path(vault)
    items = []
    for folder in _folders(vault):
        try:
            entries = sorted(os.scandir(folder), key=lambda e: e.name)
        except OSError:
            continue
        for entry in entries:
            if entry.name.startswith("."):
                continue
            if entry.name == f"{folder.name}.md":
                try:
                    items.append((entry.path, entry.stat().st_mtime_ns))
                except OSError:
                    pass
            else:
                items.append((entry.path, entry.is_dir()))
    return hash(tuple(items))


# ---------------------------------------------------------------------------
# service side: the single writer
# ---------------------------------------------------------------------------
def plugin_enabled(vault) -> bool:
    """Is the Waypoint plugin still switched on in Obsidian? Then it writes
    too, and the conflicts continue."""
    import json
    try:
        enabled = json.loads((Path(vault) / ".obsidian" / "community-plugins.json").read_text())
    except (OSError, ValueError):
        return False
    return isinstance(enabled, list) and "waypoint" in enabled


class WaypointKeeper:
    """Polls the vault structure and regenerates indexes once a change has
    settled (a sync delivers a batch over several seconds), under the
    service's vault lock. Writes only notes whose content changes."""

    def __init__(self):
        self._stop = threading.Event()
        self._thread = None
        self.last_refresh = None
        self.last_changed = []
        self.notes_written = 0
        self._lock = threading.Lock()

    def refresh_now(self) -> list:
        from .config import settings
        from .jobctx import log
        from .vaultlock import vault_lock

        with self._lock, vault_lock():
            changed = refresh(settings.vault_dir)
        self.last_refresh = time.time()
        if changed:
            self.last_changed = [str(p.relative_to(settings.vault_dir)) for p in changed]
            self.notes_written += len(changed)
            log(f"Waypoints: updated {len(changed)} folder note(s)")
        return changed

    def start(self):
        self._thread = threading.Thread(target=self._run, name="waypoints", daemon=True)
        self._thread.start()

    def stop(self):
        self._stop.set()

    def status(self) -> dict:
        from .config import settings
        return {
            "managed": settings.manage_waypoints,
            "plugin_enabled": plugin_enabled(settings.vault_dir),
            "last_refresh": self.last_refresh,
            "last_changed": self.last_changed[-10:],
            "notes_written": self.notes_written,
        }

    def _run(self):
        from .config import settings
        from .jobctx import log

        log("Waypoints: keeping folder-note indexes up to date (the Obsidian plugin should be disabled)")
        seen = pending = None
        try:
            self.refresh_now()
            seen = structure_signature(settings.vault_dir)
        except Exception as e:  # noqa: BLE001
            log(f"WARNING: waypoint refresh failed: {e}")
        while not self._stop.wait(settings.waypoint_poll_seconds):
            try:
                current = structure_signature(settings.vault_dir)
                if current == seen:
                    continue
                if current != pending:
                    pending = current  # changed - wait one more interval for it to settle
                    continue
                self.refresh_now()
                seen = pending = structure_signature(settings.vault_dir)  # includes our own writes
            except Exception as e:  # noqa: BLE001 - keep watching
                log(f"WARNING: waypoint refresh failed: {e}")


keeper = WaypointKeeper()
